mapper.update:
update voya_ai_attraction
set like_count = greatest(0, ifnull(like_count, 0) + #{delta})
where id = #{targetId}

update voya_ai_guide
set like_count = greatest(0, ifnull(like_count, 0) + #{delta})
where id = #{targetId}

mapper.select:
select l.id, l.user_id, l.target_type, l.target_id, l.create_time, u.nickname, u.avatar_url, case l.target_type when 'attraction' then a.name when 'guide' then g.title else null end as target_title, case l.target_type when 'attraction' then a.cover_image when 'guide' then g.cover_image else null end as target_cover_image, case l.target_type when 'guide' then g.summary else null end as target_summary from voya_ai_like l left join voya_ai_user u on l.user_id = u.id left join voya_ai_attraction a on l.target_type = 'attraction' and l.target_id = a.id and a.del_flag = '0' left join voya_ai_guide g on l.target_type = 'guide' and l.target_id = g.id and g.del_flag = '0'
and l.target_type = #{targetType}
and u.nickname like concat('%', #{nickname}, '%')
and l.create_time >= #{beginCreateTime}
and l.create_time < date_add(#{endCreateTime}, interval 1 day)
order by l.create_time desc, l.id desc
